<h1 class="page-title">Bewerbungen</h1>
<?php foreach ($rows as $r): ?><div class="cardx mb-3"><div class="cardx-h"><div><h3><?= e($r['username']) ?> → <?= e($r['job']) ?></h3><small><?= e($r['firstname']) ?></small></div><div class="d-flex gap-2 align-items-center"><span class="tag <?= $r['status'] === 'open' ? 'yellow' : 'gray' ?>"><?= e($r['status']) ?></span>
<?php if ($r['status'] === 'open'): ?><form method="post" action="<?= url('/admin/applications/' . (int)$r['id'] . '/close') ?>"><?= csrf_field() ?><button class="btn btn-sm btn-dark2">Abschließen</button></form><?php endif; ?></div></div>
<div class="cardx-b"><div class="bb"><?= render_text((string)$r['message']) ?></div><div class="small text-mut mt-2"><?php foreach (['monday' => 'Mo', 'tuesday' => 'Di', 'wednesday' => 'Mi', 'thursday' => 'Do', 'friday' => 'Fr', 'saturday' => 'Sa', 'sunday' => 'So'] as $k => $l) if ($r['available_' . $k]) echo $l . ': ' . e($r['available_' . $k]) . ' · '; ?></div></div></div><?php endforeach; if (!$rows): ?><p class="text-mut">Keine Bewerbungen.</p><?php endif; ?>
